<?php

namespace App\Http\Controllers\SupportTeam;

use App\Helpers\Qs;
use App\Http\Controllers\Controller;
use App\Models\Exam;
use App\Repositories\ExamRepo;
use App\Repositories\MyClassRepo;
use App\Repositories\StudentRepo;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\Auth;

class AdmitCardController extends Controller
{
    protected $exam, $my_class, $student;

    public function __construct(ExamRepo $exam, MyClassRepo $my_class, StudentRepo $student)
    {
        /* Owner ruling 2026-10-22: admit cards are generated by the
           school office (teamSA) and collected by the student/parent
           self-service below — teachers no longer open the staff
           screens at all, so the gate is teamSA, not teamSAT. */
        $this->middleware('teamSA', ['only' => ['index', 'printSheet']]);

        $this->exam = $exam;
        $this->my_class = $my_class;
        $this->student = $student;
    }

    /**
     * Staff screen: pick an exam + class (+ optional section) and get the
     * roster of students whose admit cards can be printed.
     */
    public function index(Request $req)
    {
        $d['exams'] = $this->exam->getExam(['year' => Qs::getCurrentSession()]);
        $d['my_classes'] = $this->my_class->all();
        $d['sections'] = $this->my_class->getAllSections();

        $d['exam_id'] = $req->query('exam_id');
        $d['class_id'] = $req->query('class_id');
        $d['section_id'] = $req->query('section_id');
        $d['selected'] = false;
        $d['students'] = collect();

        /* Section cascade (owner screenshot bug, 2026-10-22): the
           Section dropdown listed every section in the school, so a
           stale pick from another class (e.g. "SSS 2 – A" beside
           Class "JSS 2") survived a class change. Once a class is
           chosen, only that class's sections are offered; a submitted
           section that belongs to a different class is invalid and
           yields the clean empty state — never another class's roster. */
        if ($d['class_id']) {
            $d['sections'] = $d['sections']->where('my_class_id', (int) $d['class_id'])->values();
        }

        if ($d['exam_id'] && $d['class_id']) {
            $d['exam'] = $this->exam->find($d['exam_id']);
            // Round 9 (2026-10-28): selected used to go true on the
            // mere presence of both params, so a stale/tampered
            // exam_id reached the blade with $exam = null and died
            // with a 500 at `{{ $exam->name }}`. Only select when
            // the exam resolves — a dead exam renders the plain
            // picker, the same clean empty state Manage already
            // used for bad ids.
            if (!$d['exam']) {
                return view('pages.support_team.exams.admit_cards', $d);
            }
            $d['selected'] = true;
            if ($d['section_id'] && !$d['sections']->contains('id', (int) $d['section_id'])) {
                $d['students'] = collect();
            } else {
                $d['students'] = $this->roster($d['class_id'], $d['section_id']);
            }
        }

        return view('pages.support_team.exams.admit_cards', $d);
    }

    /**
     * Print sheet: one admit card per student in the class/section
     * (or a single student when ?student=<user_id> is present).
     */
    public function printSheet($exam_id, $class_id, Request $req)
    {
        $exam = $this->exam->find($exam_id) ?: abort(404);
        $class = $this->my_class->find($class_id) ?: abort(404);

        /* Batch 2026-10-28 (exam-timetable round 32): same scope
           rule as the date sheet (F-R31-1 writes, F-R32-1 reads).
           buildSchedule() reads exam_dates for (exam, class) with
           no scope check, so a legacy mismatched row printed a
           wrong-scope card for the whole class. Refuse before
           any schedule is built. */
        if (!empty($exam->my_class_id) && (int) $exam->my_class_id !== (int) $class->id) {
            return redirect()->route('admit_cards.index')
                ->with('flash_danger', $this->scopeMismatchMessage($exam, $class->id));
        }

        $students = $this->roster($class_id, $req->query('section_id'));

        if ($req->query('student')) {
            $students = $students->where('user_id', (int) $req->query('student'))->values();
        }

        $d['exam'] = $exam;
        $d['my_class'] = $class;
        $d['students'] = $students;
        $d['school'] = $this->schoolInfo();
        // Batch 2026-10-26 (streams): a bulk print used to give
        // every student all 12 Class 11/12 subjects, including
        // out-of-stream papers. Each streamed student now gets
        // only their own stream's schedule (built once per stream
        // and attached to the record); unstreamed students keep
        // the full class schedule.
        // The section filter (if any) picks the exam grid too:
        // a section-filtered bulk print must not read another
        // section's exam timetable (batch 2026-10-28).
        $sectionFilter = $req->query('section_id');
        $base = $this->buildSchedule($exam, $class_id, null, $sectionFilter);
        $d['schedule'] = $base['rows'];
        $d['schedule_fallback'] = $base['fallback'];
        $byStream = [];
        foreach ($students as $sr) {
            $stream = $sr->section->stream ?? null;
            if (!$stream) {
                continue;
            }
            if (!isset($byStream[$stream])) {
                $byStream[$stream] = $this->buildSchedule($exam, $class_id, $stream, $sectionFilter);
            }
            $sr->setAttribute('admit_schedule_rows', $byStream[$stream]['rows']);
            $sr->setAttribute('admit_schedule_fallback', $byStream[$stream]['fallback']);
        }

        return view('pages.support_team.exams.admit_print', $d);
    }

    /**
     * Self-service list: the logged-in student (own exams) or parent
     * (each child's exams) picks an exam to print an admit card for.
     */
    public function myCards()
    {
        $user = Auth::user();

        if (Qs::userIsTeamSA()) {
            return redirect()->route('admit_cards.index');
        }

        /* Self-service is for students and parents only. Any other
           role (teacher, accountant, librarian) has no admit-card
           surface here — owner ruling 2026-10-22 for teachers. */
        if (!in_array($user->user_type, ['student', 'parent'])) {
            return redirect(route('dashboard'))->with('pop_error', __('msg.denied'));
        }

        if ($user->user_type === 'parent') {
            $d['records'] = Qs::findMyChildren($user->id);
        } else {
            $sr = Qs::getSRByUserID($user->id);
            $d['records'] = $sr ? collect([$sr]) : collect();
        }

        $d['exams'] = $this->exam->getExam(['year' => Qs::getCurrentSession()]);

        $session = Qs::getCurrentSession();
        $d['current_session'] = $session;
        $d['viewer_is_parent'] = $user->user_type === 'parent';
        $d['due_by_student'] = [];
        foreach ($d['records'] as $sr) {
            $d['due_by_student'][$sr->user_id] = \App\Support\FeeDefaulter::outstandingFor($sr->user_id, $session);
        }

        /* ONE-TIME GENERATION freeze (owner standing rule
           2026-11-08): for a published exam, the list shows the
           exam identity as frozen at publish time, not a later
           live rename — the same frozen payload the card itself
           renders from. $d['frozen_exams'][student_id][exam_id]
           carries the frozen exam display (name / term / year). */
        $d['frozen_exams'] = [];
        $examIds = $d['exams']->pluck('id')->all();
        $userIds = $d['records']->pluck('user_id')->all();
        if (!empty($examIds) && !empty($userIds)) {
            $snaps = \App\Models\AdmitCardSnapshot::whereIn('exam_id', $examIds)
                ->whereIn('student_id', $userIds)
                ->get();
            foreach ($snaps as $snap) {
                $d['frozen_exams'][$snap->student_id][$snap->exam_id] = $snap->payload['exam'] ?? null;
            }
        }

        return view('pages.support_team.exams.admit_my', $d);
    }

    /**
     * Fee-defaulter document block (owner ruling 2026-10-22): a
     * student whose current-session fees are outstanding — or their
     * parent — cannot generate the admit card until the dues are
     * paid. The definition is App\Support\FeeDefaulter's, the very
     * one the Fee Defaulters page lists, so the block lifts itself
     * the moment the balance clears. teamSA (the school office)
     * generation is never blocked, and the notice view receives no
     * document data at all. Returns the notice response, or null
     * when generation proceeds. Mirrors MarkController::feeDefaulterBlock.
     */
    protected function feeDefaulterBlock($student_id, $document)
    {
        if (Qs::userIsTeamSA()) {
            return null;
        }

        $due = \App\Support\FeeDefaulter::outstandingFor($student_id, Qs::getCurrentSession());
        if ($due <= 0) {
            return null;
        }

        return view('pages.support_team.fee_blocked', [
            'document' => $document,
            'sr' => $this->student->getRecord(['user_id' => $student_id])->first(),
            'due' => $due,
            'year' => Qs::getCurrentSession(),
            'viewer_is_parent' => Qs::userIsMyChild($student_id, Auth::user()->id),
        ]);
    }

    /**
     * Self-service card: a student prints their own card, a parent prints
     * a card for one of their children. Office staff (teamSA) may also
     * use it. Anyone else gets a 403 — teachers included (owner ruling
     * 2026-10-22: the former teamSAT allowance let any teacher print
     * any student's card through this URL).
     */
    public function myCard($exam_id, $student_id)
    {
        $user = Auth::user();
        $student_id = (int) $student_id;

        $allowed = $user->id === $student_id
            || Qs::userIsMyChild($student_id, $user->id)
            || Qs::userIsTeamSA();

        if (!$allowed) {
            abort(403);
        }

        $exam = $this->exam->find($exam_id) ?: abort(404);
        $sr = $this->student->getRecord(['user_id' => $student_id])->first() ?: abort(404);

        /* Batch 2026-10-28 (exam-timetable round 32): scope check
           before the fee block — a scoped exam for another class
           is not this student's exam at all, so the scope refusal
           (not the fee block) is the truthful response. */
        if (!empty($exam->my_class_id) && (int) $exam->my_class_id !== (int) $sr->my_class_id) {
            return redirect()->route('admit_cards.my')
                ->with('flash_danger', $this->scopeMismatchMessage($exam, $sr->my_class_id));
        }

        /* Publication gate (owner order 2026-11-08): a student or
           parent gets the card only once the Principal has
           published this exam's admit cards — until then the
           shared not-published state renders, and it is checked
           BEFORE the fee block (an unpublished card is not a fee
           matter). teamSA office generation is never blocked —
           the office prints whenever it needs to. */
        if (!Qs::userIsTeamSA() && !$exam->admit_cards_published) {
            return view('pages.support_team.not_published', [
                'page_title' => 'Admit Card — Not Published Yet',
                'document' => 'Admit Card',
                'icon' => 'icon-profile',
                'detail' => 'Admit cards for ' . $exam->name . ' (' . $exam->year . ') have not been published yet.',
            ]);
        }

        /* Fee-defaulter document block (owner ruling 2026-10-22):
           teamSA office generation above (index / printSheet) is
           never blocked — the helper exempts teamSA itself. The
           fee gate stays LIVE even for a frozen card: it is
           evaluated here, before any snapshot is read, so a card
           frozen at publish still blocks a student whose dues are
           unpaid (owner-approved freeze scope, 2026-11-08). */
        if ($block = $this->feeDefaulterBlock($student_id, 'Admit Card')) {
            return $block;
        }

        /* ONE-TIME GENERATION freeze (owner standing rule
           2026-11-08): a student or parent sees the card exactly
           as it was frozen when the Principal published it — the
           snapshot payload, never a live rebuild, so a later
           section transfer, branding change or date-sheet
           correction cannot rewrite a released card. teamSA keeps
           the live render (the office is the correction surface).
           No snapshot (the exam was published before the freeze
           existed, or the student joined after publishing) falls
           back to the live render below. */
        if (!Qs::userIsTeamSA()) {
            $payload = \App\Support\AdmitCardFreezer::payloadFor($exam->id, $student_id);
            if ($payload) {
                return view('pages.support_team.exams.admit_print', \App\Support\AdmitCardFreezer::viewData($payload));
            }
        }

        $sr->load('section.teacher');

        $d['exam'] = $exam;
        $d['my_class'] = $this->my_class->find($sr->my_class_id);
        $d['students'] = collect([$sr]);
        $d['school'] = $this->schoolInfo();
        $schedule = $this->buildSchedule($exam, $sr->my_class_id, $sr->section->stream ?? null, $sr->section_id);
        $d['schedule'] = $schedule['rows'];
        $d['schedule_fallback'] = $schedule['fallback'];

        return view('pages.support_team.exams.admit_print', $d);
    }

    /**
     * Active (non-graduated) students of a class, optionally one section,
     * sorted by name — the same population StudentRepo::findStudentsByClass
     * returns, with section eager-loaded for the roster/card.
     */
    protected function roster($class_id, $section_id = null)
    {
        $q = $this->student->activeStudents()
            ->where('my_class_id', $class_id)
            ->with(['user', 'my_class', 'section', 'section.teacher']);

        if ($section_id) {
            $q->where('section_id', $section_id);
        }

        return $q->get()->sortBy('user.name')->values();
    }

    /**
     * Round 32 scope message, mirroring ExamDateController's
     * R31 wording so the refusal reads identically on the date
     * sheet and on the admit card: "This exam is scoped to {X}
     * — it cannot carry dates for {Y}."
     */
    protected function scopeMismatchMessage($exam, $classId)
    {
        $scopedClass = $this->my_class->find($exam->my_class_id);
        $targetClass = $this->my_class->find($classId);
        return 'This exam is scoped to ' . ($scopedClass ? $scopedClass->name : 'one class')
            . ' — it cannot carry dates for ' . ($targetClass ? $targetClass->name : 'this class') . '.';
    }

    /**
     * Subject schedule for an exam + class. Sources, in order:
     * (1) the exam timetable for the class (time_table_records ->
     * time_tables.exam_date + time_slots.full); (2) the generated
     * date sheet (exam_dates) — the admin's "Generate" run. Before
     * this fix the card read ONLY source (1), so a generated date
     * sheet never reached the card and it fell back to dateless
     * subjects even though dates existed. When neither source has
     * dates, fall back to the class's subject list with no dates —
     * dates are never invented.
     */
    protected function buildSchedule(Exam $exam, $class_id, $stream = null, $section_id = null)
    {
        /* The builder lives in App\Support\AdmitCardBuilder since
           2026-11-08 so the publish-time freeze
           (App\Support\AdmitCardFreezer) snapshots exactly what
           this live path renders — one source of truth. */
        return \App\Support\AdmitCardBuilder::buildSchedule($exam, $class_id, $stream, $section_id);
    }

    protected function schoolInfo()
    {
        return \App\Support\AdmitCardBuilder::schoolInfo();
    }
}
